*** Begin Patch
*** Update File: /home/dastan/Recommender Systems/Week 6/graph.js
@@
 function buildGraph(train) {
-  // TODO(hw6): collect observed ids, map them to contiguous indices, fill R and
-  // degree, then return the object described in the typedef and readme 3.1.
-  throw new Error("TODO(hw6): buildGraph is not implemented yet.");
+  const records = Array.isArray(train) ? train : [];
+  for (const r of records) {
+    if (!r || !Number.isInteger(r.userId) || r.userId <= 0 ||
+        !Number.isInteger(r.movieId) || r.movieId <= 0 || !Number.isFinite(r.rating)) {
+      throw new Error("buildGraph: records require positive integer IDs and finite ratings.");
+    }
+  }
+  const userIds = Array.from(new Set(records.map(r => r.userId))).sort((a, b) => a - b);
+  const movieIds = Array.from(new Set(records.map(r => r.movieId))).sort((a, b) => a - b);
+  const nUsers = userIds.length;
+  const nMovies = movieIds.length;
+  const userIndexOf = new Map(userIds.map((id, i) => [id, i]));
+  const movieIndexOf = new Map(movieIds.map((id, i) => [id, i]));
+  const nodeCount = nUsers + nMovies;
+  const R = Array.from({ length: nUsers }, () => new Array(nMovies).fill(0));
+  const degree = new Float64Array(nodeCount);
+  let positiveEdges = 0;
+  for (const r of records) {
+    const u = userIndexOf.get(r.userId);
+    const i = movieIndexOf.get(r.movieId);
+    if (r.rating >= 4 && R[u][i] === 0) {
+      R[u][i] = 1;
+      degree[u]++;
+      degree[nUsers + i]++;
+      positiveEdges++;
+    }
+  }
+  return {
+    nUsers, nMovies, userIds, movieIds, userIndexOf, movieIndexOf, nodeCount,
+    nodeOfUser: id => userIndexOf.get(Number(id)) ?? -1,
+    movieOfNode: node => Number.isInteger(node) && node >= nUsers && node < nodeCount
+      ? movieIds[node - nUsers] : -1,
+    isUserNode: node => Number.isInteger(node) && node >= 0 && node < nUsers,
+    degree,
+    zeroDegreeUsers: userIds.filter((id, u) => degree[u] === 0),
+    zeroDegreeMovies: movieIds.filter((id, i) => degree[nUsers + i] === 0),
+    positiveEdges, R,
+  };
 }
@@
 function rowNormalize(graph) {
-  // TODO(hw6): normalize positive-degree rows and build the dangling mask.
-  throw new Error("TODO(hw6): rowNormalize is not implemented yet.");
+  if (!graph) return { Q: [], danglingMask: [] };
+  // This dense, inspectable representation is for verification. MovieLens
+  // propagation below uses R directly and never calls this square allocator.
+  const n = graph.nodeCount;
