/**
 * Train the factorization with batched gradient descent.
 *
 * TODO(hw5): run a mini-batch loop over `train` using the TF.js optimizer.
 * Score each batch with tensor ops (never one `tf` call per rating) and let the
 * optimizer update both variables in place:
 * ```js
 * const optimizer = tf.train.adam(lr);
 * for (let epoch = 1; epoch <= epochs; epoch++) {
 *   for (const batch of batches) {
 *     optimizer.minimize(() => tf.tidy(() => {
 *       const u = tf.gather(model.userFactors, batch.userIdx);
 *       const i = tf.gather(model.itemFactors, batch.itemIdx);
 *       const pred = tf.sum(u.mul(i), 1).add(model.globalMean);
 *       const mse = tf.losses.meanSquaredError(batch.targets, pred);
 *       const l2 = model.userFactors.square().sum()
 *         .add(model.itemFactors.square().sum()).mul(reg);
 *       return mse.add(l2);
 *     }), false, [model.userFactors, model.itemFactors]).dispose();
 *   }
 *   trainingHistory.push({
 *     epoch,
 *     trainRMSE: computeRMSEFor(train),
 *     valRMSE: computeRMSEFor(val),
 *   });
 * }
 * return trainingHistory;
 * ```
 * Key TF.js APIs to use: `tf.train.adam(lr)` (or `tf.train.sgd`),
 * `optimizer.minimize(fn, returnCost, varList)`, `tf.gather`,
 * `tf.losses.meanSquaredError`, and `tf.tidy` for per-batch intermediates.
 * `minimize` returns a scalar loss tensor — dispose it (or use `tf.tidy`) so
 * the loop does not accumulate tensors.
 *
 * Contract:
 *  - `opts = { epochs, lr, reg, batchSize }`. Use mini-batches of `batchSize`
 *    (or full-batch when `batchSize >= train.length`).
 *  - Update `model` in place. Do NOT reallocate it.
 *  - Append one `HistoryRow` per epoch to the module-level `trainingHistory`
 *    and return it: `{ epoch, trainRMSE: computeRMSEFor(train),
 *    valRMSE: computeRMSEFor(val) }`. `epoch` is 1-based.
 *  - Shuffling the batch order each epoch is allowed and usually helps.
 *  - Guard `train.length === 0` by returning an empty history.
 *
 * @param {Rating[]} train
 * @param {Rating[]} val
 * @param {TrainOptions} opts
 * @returns {HistoryRow[]}
 */
function trainMF(train, val, opts) {
  trainingHistory = [];
  if (train.length === 0) return trainingHistory;

  const { epochs, lr, reg } = opts;
  const batchSize = Math.max(1, Math.floor(opts.batchSize));
  const optimizer = tf.train.adam(lr);
  const userIds = Int32Array.from(train, (r) => r.userId);
  const itemIds = Int32Array.from(train, (r) => r.movieId);
  const targets = Float32Array.from(train, (r) => r.rating);
  let bestRow = null;
  let bestUsers = null;
  let bestItems = null;

  try {
    for (let epoch = 1; epoch <= epochs; epoch++) {
      for (let start = 0; start < train.length; start += batchSize) {
        const end = Math.min(start + batchSize, train.length);
        tf.tidy(() => {
          const userIdx = tf.tensor1d(userIds.subarray(start, end), "int32");
          const itemIdx = tf.tensor1d(itemIds.subarray(start, end), "int32");
          const actual = tf.tensor1d(targets.subarray(start, end));
          // returnCost=false returns no loss tensor; tidy releases intermediates.
          optimizer.minimize(() => {
            const u = tf.gather(model.userFactors, userIdx);
            const i = tf.gather(model.itemFactors, itemIdx);
            const pred = tf.sum(u.mul(i), 1).add(model.globalMean);
            const mse = tf.losses.meanSquaredError(actual, pred);
            // Average squared row norms over this batch, matching the MSE scale.
            // Penalize participating rows, not every factor at every batch update.
            const l2 = u.square().sum(1).add(i.square().sum(1)).mean().mul(reg);
            return mse.add(l2);
          }, false, [model.userFactors, model.itemFactors]);
        });
      }

      const row = {
        epoch,
        trainRMSE: computeRMSEFor(train),
        valRMSE: computeRMSEFor(val),
      };
      trainingHistory.push(row);
      // Epochs are ascending: strict improvement preserves the earliest tie.
      if (bestRow === null || row.valRMSE < bestRow.valRMSE) {
        tf.dispose([bestUsers, bestItems]);
        bestUsers = model.userFactors.clone();
        bestItems = model.itemFactors.clone();
        bestRow = row;
      }
    }

    if (bestRow) {
      model.userFactors.assign(bestUsers);
      model.itemFactors.assign(bestItems);
    }
    return trainingHistory;
  } finally {
    tf.dispose([bestUsers, bestItems]);
    optimizer.dispose();
  }
}

