/**
 * Build the bipartite user-movie graph from the TRAINING split.
 *
 * Implemented rules (readme.md section 3.1):
 *  - The node universe is the set of user ids and movie ids observed in
 *    `train` ONLY. Map ids to contiguous indices explicitly; never add a
 *    padding node (no index-0 "dummy" row).
 *  - Node order is users first, then movies:
 *      user u  -> global node userIndexOf.get(u) in [0, nUsers)
 *      movie m -> global node nUsers + movieIndexOf.get(m) in [nUsers, nUsers + nMovies)
 *    The graph view relies on this exact order (it treats node < nUsers as a
 *    user node and indexes degree by the global node index).
 *  - R[u][i] = 1 iff user u rated movie i with rating >= 4.0 in TRAINING, else
 *    0. A zero is "no positive edge", not a negative opinion.
 *  - degree is the bipartite degree over BOTH node kinds.
 *
 * Assumptions: `train` is an array of {userId, movieId, rating, timestamp}
 * records; ratings >= 4.0 are positives. Failure cases: a non-array `train`
 * should be treated as empty (return an empty graph) rather than throwing.
 * Malformed records with invalid IDs or non-finite ratings throw an Error.
 * Duplicate positives count once; later low ratings do not erase an edge.
 *
 * @param {Rating[]} train
 * @returns {Graph}
 */
function buildGraph(train) {
  const records = Array.isArray(train) ? train : [];
  for (const r of records) {
    if (!r || !Number.isInteger(r.userId) || r.userId <= 0 ||
        !Number.isInteger(r.movieId) || r.movieId <= 0 || !Number.isFinite(r.rating)) {
      throw new Error("buildGraph: records require positive integer IDs and finite ratings.");
    }
  }
  const userIds = Array.from(new Set(records.map(r => r.userId))).sort((a, b) => a - b);
  const movieIds = Array.from(new Set(records.map(r => r.movieId))).sort((a, b) => a - b);
  const nUsers = userIds.length;
  const nMovies = movieIds.length;
  const userIndexOf = new Map(userIds.map((id, i) => [id, i]));
  const movieIndexOf = new Map(movieIds.map((id, i) => [id, i]));
  const nodeCount = nUsers + nMovies;
  const R = Array.from({ length: nUsers }, () => new Array(nMovies).fill(0));
  const degree = new Float64Array(nodeCount);
  let positiveEdges = 0;
  for (const r of records) {
    const u = userIndexOf.get(r.userId);
    const i = movieIndexOf.get(r.movieId);
    if (r.rating >= 4 && R[u][i] === 0) {
      R[u][i] = 1;
      degree[u]++;
      degree[nUsers + i]++;
      positiveEdges++;
    }
  }
  return {
    nUsers, nMovies, userIds, movieIds, userIndexOf, movieIndexOf, nodeCount,
    nodeOfUser: id => userIndexOf.get(Number(id)) ?? -1,
    movieOfNode: node => Number.isInteger(node) && node >= nUsers && node < nodeCount
      ? movieIds[node - nUsers] : -1,
    isUserNode: node => Number.isInteger(node) && node >= 0 && node < nUsers,
    degree,
    zeroDegreeUsers: userIds.filter((id, u) => degree[u] === 0),
    zeroDegreeMovies: movieIds.filter((id, i) => degree[nUsers + i] === 0),
    positiveEdges, R,
  };
}

/**
 * Row-normalize the transition matrix and record the zero-degree nodes.
 *
 * For each positive-degree node, divide its row by its degree so the
 * row sums to 1; leave zero-degree rows all-zero and mark them in
 * `danglingMask`. The dangling mass must be handled in the update exactly as in
 * readme.md section 3.3:
 *
 *   p_next = alpha * (Q^T * p + d * v) + (1 - alpha) * v
 *
 * where d is the probability mass currently sitting on zero-degree nodes.
 *
 * MEMORY POLICY (readme.md section 3.5): this helper exposes a dense square Q
 * solely for inspection/tests. The MovieLens propagation path does not call
 * it: rectangular matMul (CPU/WebGL) or sparse segment reduction (WASM) applies
 * the same bipartite transition. Only opts.transition uses tf.tensor2d(Q).
 * Q and danglingMask remain plain arrays for backend-independent inspection.
 *
 * Assumptions: `graph` comes from `buildGraph` (node order users then movies).
 * Failure cases: a null/missing graph returns { Q: [], danglingMask: [] }.
 *
 * @param {Graph} graph
 * @returns {RowNormalized}
 */
function rowNormalize(graph) {
  if (!graph) return { Q: [], danglingMask: [] };
  // This dense, inspectable representation is for verification. MovieLens
  // propagation below uses R directly and never calls this square allocator.
  const n = graph.nodeCount;
  const Q = Array.from({ length: n }, () => new Array(n).fill(0));
  const danglingMask = Array.from(graph.degree, degree => degree === 0);
  for (let u = 0; u < graph.nUsers; u++) {
    for (let i = 0; i < graph.nMovies; i++) {
      if (!graph.R[u][i]) continue;
      const m = graph.nUsers + i;
      Q[u][m] = graph.R[u][i] / graph.degree[u];
      Q[m][u] = graph.R[u][i] / graph.degree[m];
    }
  }
  return { Q, danglingMask };
}

/**
 * Global PageRank with a uniform restart distribution.
 *
 * Power iteration with a uniform restart vector v
 * (readme.md sections 3.2-3.4), using TensorFlow.js for the batched
 * propagation:
 *
 *   p_0 = v ;  p_next = alpha * (Q^T * p + d * v) + (1 - alpha) * v
 *
 * Initialize p to v. Stop when the L1 difference between consecutive
 * distributions is below `tol`, or after `maxIter` iterations; an iteration cap
 * is NOT proof of convergence, so `converged` must be false when the cap is
 * hit. Do not force any node's score to equal the restart probability.
 *
 * TRANSITION SOURCE - part of the contract you must implement:
 *  - `opts.transition` present (a {@link TransitionSpec}, e.g.
 *    `REFERENCE_GRAPH.transition`): propagate on THAT matrix and do not require
 *    the global `GRAPH`. `Q` is already row-normalized, so do not re-normalize
 *    it; read `danglingMask` by position (`danglingMask[i]` is 1 iff node `i` is
 *    zero-degree). This is how the HW6 harness runs your implementation on the
 *    4-node reference fixture.
 *  - `opts.transition` absent: behave exactly as for MovieLens - require the
 *    global `GRAPH` (from `buildGraph` + `rowNormalize`) and build the
 *    transition from its `R` / `degree`.
 *  - Neither present: throw a clear Error; never silently fall back to a
 *    uniform distribution.
 *
 * NODE-INDEX CONVENTION: node indices are global positions. For the MovieLens
 * graph they follow `buildGraph` (users `[0, nUsers)`, then movies
 * `[nUsers, nUsers + nMovies)`, no padding node). For a supplied
 * `opts.transition` they follow `Q`'s own order. `p[i]` is the probability of
 * node `i` in that same order.
 *
 * The zero-degree policy must be identical here and in `personalizedPageRank`.
 *
 * @param {number} alpha Link-following probability in [0, 1]; 1 - alpha restarts.
 * @param {{tol?: number, maxIter?: number, transition?: TransitionSpec}} [opts]
 *   Defaults tol = 1e-6, maxIter = 500, transition absent (use the global GRAPH).
 * @returns {PageRankResult} `{p, iterations, residual, converged}`: `p` is a
 *   Float64Array over node indices that sums to ~1; `iterations` is the number
 *   of updates performed; `residual` is the final L1 difference
 *   `sum_j |p_next[j] - p[j]|`; `converged` is true only when `residual < tol`
 *   before the iteration cap was reached.
 * @throws {Error} when neither `opts.transition` nor the global `GRAPH` exists.
 */
function pageRank(alpha, opts) {
  return graphStudentPropagate(null, alpha, opts);
}

/**
 * Personalized PageRank with a one-hot restart at one user's node.
 *
 * Identical to `pageRank` except the restart vector v is one-hot at
 * one node. It accepts the same `opts.transition` override, the same stopping
 * rule, the same zero-degree policy and the same return shape
 * `{p, iterations, residual, converged}`.
 *
 * RESTART INDEX (node index, not a raw user id): the first argument is a node
 * INDEX and is used directly as the restart node. This is today's caller
 * convention; keep it.
 *  - default MovieLens path: the index is a global node index from `buildGraph`
 *    (a user node is `GRAPH.nodeOfUser(userId)` or equivalently any
 *    `index < GRAPH.nUsers`).
 *  - `opts.transition` path: the index must be in `[0, Q.length)` and refers to
 *    the same node order as `Q` (`REFERENCE_GRAPH.transition.nodeLabels` names
 *    the fixture's nodes for display).
 *
 * FAILURE CASES: an unknown / out-of-range restart index must throw a clear
 * Error naming the index rather than silently falling back to a uniform
 * restart; and when neither `opts.transition` nor the global `GRAPH` is
 * available, throw instead of guessing.
 *
 * @param {number} userId Node index of the restart node (see RESTART INDEX).
 * @param {number} alpha  Link-following probability in [0, 1]; 1 - alpha restarts.
 * @param {{tol?: number, maxIter?: number, transition?: TransitionSpec}} [opts]
 *   Same options as `pageRank`; defaults tol = 1e-6, maxIter = 500, transition
 *   absent (use the global GRAPH).
 * @returns {PageRankResult} `{p, iterations, residual, converged}` (see `pageRank`).
 * @throws {Error} when the restart index is unknown / out of range, or when
 *   neither `opts.transition` nor the global `GRAPH` exists.
 */
function personalizedPageRank(userId, alpha, opts) {
  if (!Number.isInteger(userId) || userId < 0) {
    throw new Error("personalizedPageRank: invalid restart node index " + String(userId));
  }
  return graphStudentPropagate(userId, alpha, opts);
}

/**
 * Plain-array memoization for an immutable graph, one option tuple at a time.
 * Weak keys allow discarded graphs to be collected; no tensors are retained.
 * Matches the instructor cache's graph-identity assumption. Returned vectors
 * are copied so callers cannot mutate cached probabilities. At MovieLens size,
 * one full user population occupies about 19 MB of probability-array storage.
 */
const graphStudentPropagationCache = new WeakMap();

/**
 * Shared synchronous tensor power iteration for the two student entry points.
 * A null seed means uniform restart; otherwise seed is a GLOBAL NODE INDEX.
 * Explicit transitions are validated, never re-normalized. The MovieLens path
 * keeps rectangular R (CPU/WebGL), or incoming source/segment indices (WASM),
 * plus degree vectors, never a square Q. WASM's fused sparseSegmentSum avoids
 * multiplying structural zeros. Indices are derived from binary R once per
 * call; propagation itself stays entirely in tensor operations. Missing
 * segments are zero, and trailing isolated destinations are padded with zero
 * output rows to the EXISTING node count, never added as graph nodes.
 * All tensors are owned by this call and disposed even on failure. Synchronous
 * dataSync reads preserve the instructor adapters' non-Promise return contract.
 *
 * @param {number|null} seed Restart position, not a raw MovieLens user ID.
 * @param {number} alpha Link-following probability in [0, 1].
 * @param {Object} [opts] tol > 0; integer maxIter >= 0; optional TransitionSpec.
 * @returns {PageRankResult} Float64Array output (tensor arithmetic is float32).
 * @throws {Error} For missing/empty graphs, invalid options or transitions/seeds.
 */
function graphStudentPropagate(seed, alpha, opts) {
  const options = opts || {};
  const tol = options.tol === undefined ? 1e-6 : options.tol;
  const maxIter = options.maxIter === undefined ? 500 : options.maxIter;
  if (!Number.isFinite(alpha) || alpha < 0 || alpha > 1 ||
      !Number.isFinite(tol) || tol <= 0 || !Number.isInteger(maxIter) || maxIter < 0) {
    throw new Error("PageRank: require alpha in [0, 1], tol > 0 and integer maxIter >= 0.");
  }
  const explicit = options.transition !== undefined;
  const transition = options.transition;
  const graph = explicit ? null : getGraph();
  if (!explicit && !graph) throw new Error("PageRank: no active graph or explicit transition.");
  if (explicit && (!transition || !Array.isArray(transition.Q))) {
    throw new Error("PageRank: explicit transition must contain a square Q.");
  }
  const n = explicit ? transition.Q.length : graph.nodeCount;
  if (!Number.isInteger(n) || n <= 0) throw new Error("PageRank: cannot propagate on an empty graph.");
  if (seed !== null && (!Number.isInteger(seed) || seed < 0 || seed >= n)) {
    throw new Error("personalizedPageRank: invalid restart node index " + String(seed) + " for " + n + " nodes.");
  }
  const mask = explicit ? transition.danglingMask : Array.from(graph.degree, d => d === 0);
  if (!mask || mask.length !== n) throw new Error("PageRank: dangling mask length mismatch.");
  if (explicit) {
    for (let i = 0; i < n; i++) {
      const row = transition.Q[i];
      if (!row || row.length !== n) throw new Error("PageRank: Q must be square.");
      let sum = 0;
      for (const value of row) {
        if (!Number.isFinite(value) || value < 0) throw new Error("PageRank: Q entries must be finite and nonnegative.");
        sum += value;
      }
      if (Math.abs(sum - (mask[i] ? 0 : 1)) > 1e-6) {
        throw new Error("PageRank: Q row " + i + " disagrees with its normalization/dangling mask.");
      }
    }
  }
  if (typeof tf === "undefined") throw new Error("PageRank: TensorFlow.js is unavailable.");
  const sparse = !explicit && tf.getBackend() === "wasm";
  let cache = null;
  if (sparse) {
    const key = JSON.stringify([tf.getBackend(), alpha, tol, maxIter]);
    cache = graphStudentPropagationCache.get(graph);
    if (!cache || cache.key !== key) {
      cache = { key, results: new Map() };
      graphStudentPropagationCache.set(graph, cache);
    }
    const saved = cache.results.get(seed);
    if (saved) return { ...saved, p: saved.p.slice() };
  }
  const restart = new Float32Array(n);
  if (seed === null) restart.fill(1 / n);
  else restart[seed] = 1;
  let tensors = null;
  let p = null;
  let iterations = 0;
  let residual = Infinity;
  try {
    tensors = tf.tidy(() => {
      const shared = {
        v: tf.tensor2d(restart, [n, 1]),
        mask: tf.tensor2d(Float32Array.from(mask, x => x ? 1 : 0), [n, 1]),
      };
      if (explicit) return { ...shared, Q: tf.tensor2d(transition.Q, [n, n]) };
      const inverse = Array.from(graph.degree, d => d > 0 ? 1 / d : 0);
      if (sparse) {
        const sources = [];
        const destinations = [];
        // Sorted destination segments represent BOTH off-diagonal blocks.
        // This is graph preprocessing, not a JavaScript propagation loop.
        for (let destination = 0; destination < n; destination++) {
          if (destination < graph.nUsers) {
            for (let i = 0; i < graph.nMovies; i++) {
              if (graph.R[destination][i]) {
                sources.push(graph.nUsers + i);
                destinations.push(destination);
              }
            }
          } else {
            const i = destination - graph.nUsers;
            for (let u = 0; u < graph.nUsers; u++) {
              if (graph.R[u][i]) {
                sources.push(u);
                destinations.push(destination);
              }
            }
          }
        }
        return { ...shared, inverse: tf.tensor2d(inverse, [n, 1]),
          sources: tf.tensor1d(sources, "int32"),
          destinations: tf.tensor1d(destinations, "int32"),
          segmentCount: destinations.length ? destinations[destinations.length - 1] + 1 : 0 };
      }
      return {
        ...shared,
        R: tf.tensor2d(graph.R, [graph.nUsers, graph.nMovies]),
        invU: tf.tensor2d(inverse.slice(0, graph.nUsers), [graph.nUsers, 1]),
        invM: tf.tensor2d(inverse.slice(graph.nUsers), [graph.nMovies, 1]),
      };
    });
    p = tensors.v.clone();
    while (iterations < maxIter) {
      const step = tf.tidy(() => {
        let incoming;
        if (explicit) {
          incoming = tf.matMul(tensors.Q, p, true, false);
        } else if (sparse) {
          incoming = tensors.segmentCount === 0 ? tf.zerosLike(p) : tf.pad(
            tf.sparse.sparseSegmentSum(p.mul(tensors.inverse), tensors.sources, tensors.destinations),
            [[0, n - tensors.segmentCount], [0, 0]],
          );
        } else {
          const pu = p.slice([0, 0], [graph.nUsers, 1]).mul(tensors.invU);
          const pm = p.slice([graph.nUsers, 0], [graph.nMovies, 1]).mul(tensors.invM);
          incoming = tf.concat([
            tf.matMul(tensors.R, pm),
            tf.matMul(tensors.R, pu, true, false),
          ], 0);
        }
        const dangling = p.mul(tensors.mask).sum();
        const next = incoming.add(tensors.v.mul(dangling)).mul(alpha)
          .add(tensors.v.mul(1 - alpha));
        const delta = next.sub(p).abs().sum().dataSync()[0];
        return { next, delta };
      });
      p.dispose();
      p = step.next;
      residual = step.delta;
      iterations++;
      if (!Number.isFinite(residual)) throw new Error("PageRank: non-finite propagation residual.");
      if (residual < tol) break;
    }
    // The original contract conservatively requires tolerance BEFORE the cap.
    const result = { p: Float64Array.from(p.dataSync()), iterations, residual,
      converged: residual < tol && iterations < maxIter };
    if (cache) cache.results.set(seed, { ...result, p: result.p.slice() });
    return result;
  } finally {
    if (p) p.dispose();
    if (tensors) tf.dispose(tensors);
  }
}

